SourceCode.Declaration:
/// <summary>
/// Batch service class for Post sales order Sales processing
/// </summary>
class METPickDirectorDataService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METPickDirectorDataTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METPickDirectorDataTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:METPickDirectorData";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METPickDirectorDataContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METPickDirectorDataContract contract = dataContract as METPickDirectorDataContract;
    this.processSalesIdGeneration(contract);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METPickDirectorDataContract contract = _taskDataContract as METPickDirectorDataContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METPickDirectorDataContract();
}

/// <summary>
/// Process sales orders to substitute from the query and insert SO number in <c>METPickDirectorQueue</c>
/// </summary>
/// <param name = "_contract">_contract</param>
void processSalesIdGeneration(METPickDirectorDataContract  _contract)
{
    SalesTable salesTable;
    RecordInsertList salesIdListRecordList;
    METPickDirectorQueue postQueue;
    METPickDirectorData pickDirectorData;
    #OCCRetryCount

    METPickDirectorQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    salesIdListRecordList = new RecordInsertList(tableNum(METPickDirectorQueue));
    this.topPickingProcessId = newGuid();

    while select SalesId from pickDirectorData group by pickDirectorData.SalesId
            where pickDirectorData.PickDirectorStatus != METPickDirectorStatuses::Processed
        exists join salesTable
            where salesTable.SalesId == pickDirectorData.SalesId
    {
        try
        {
            ttsbegin;
            postQueue.clear();
            postQueue.SalesId = pickDirectorData.SalesId;
            postQueue.ProcessId = this.topPickingProcessId;
            salesIdListRecordList.add(postQueue);
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            exceptionTextFallThrough();
        }
    }
    salesIdListRecordList.insertDatabase();
}
